const YEAR=/(?:19[2-9]\d|20[0-4]\d)/g;
const JUNK=/(?:^|[ ._\-])(2160p|1080[pi]|720p|576p|480p|4k|uhd|hdr10?\+?|hdr|dv|dolby[ ._\-]?vision|web[ ._\-]?dl|webrip|bluray|blu[ ._\-]?ray|brrip|bdrip|dvdrip|hdtv|hdrip|remux|x264|x265|h[ ._]?264|h[ ._]?265|hevc|avc|10bit|aac\d?|ac3|eac3|ddp?\d?|dts|atmos|truehd|nf|amzn|hmax|dsnp|atvp|proper|repack|extended|unrated|remastered|imax|multi|dual[ ._\-]?audio|subbed|dubbed|esub|msubs?)(?:$|[ ._\-])/i;
export function clean(s){return s.replace(/[._]/g,' ').replace(/\s+/g,' ').replace(/^[\s\-–—.,:)\]}]+|[\s\-–—.,:([{]+$/g,'').trim()}
export function key(s){return s.toLowerCase().replace(/[^\p{L}\p{N}]/gu,'')}
function cut(s){const m=JUNK.exec(s);return m?s.slice(0,m.index):s}
function titleYear(s){const stripped=s.replace(/\[[^\]]*\]/g,' ').replace(/\((?![^)]*(?:19|20)\d\d)[^)]*\)/g,' ');const years=[...stripped.matchAll(YEAR)].filter(m=>m.index>0&&clean(stripped.slice(0,m.index)));const y=years.at(-1);return {title:clean(y?stripped.slice(0,y.index):cut(stripped)),year:y?Number(y[0]):null}}
export function parseName(name,path=''){
 const base=name.replace(/\.[^.]+$/,'');const dirs=path.split('/').filter(Boolean);const seasonDir=/^(?:season|series|s)[ ._\-]*(\d{1,2})$/i;
 let m=/(?:^|[^a-z0-9])s(\d{1,2})[ ._\-]*e(\d{1,3})(?!\d)/i.exec(base)||/(?:^|[^a-z0-9])(\d{1,2})x(\d{2,3})(?![0-9p])/i.exec(base)||/\bseason[ ._\-]*(\d{1,2})[ ._\-]*(?:episode|ep)[ ._\-]*(\d{1,3})\b/i.exec(base);
 let season=m?Number(m[1]):null,episode=m?Number(m[2]):null,before=m?base.slice(0,m.index):'',after=m?base.slice(m.index+m[0].length):'';
 if(!m){const sf=seasonDir.exec(dirs.at(-1)||'');const em=/(?:^|[ ._\-])(?:episode|ep|e)[ ._\-]*(\d{1,3})(?!\d)/i.exec(base)||/^(\d{1,3})(?:[ ._\-]+|$)/.exec(base);if(sf&&em){season=Number(sf[1]);episode=Number(em[1]);before=base.slice(0,em.index);after=base.slice(em.index+em[0].length)}}
 if(season!==null){let parsed=titleYear(before);if(!parsed.title)parsed=titleYear(dirs.findLast(d=>!seasonDir.test(d))||'Unknown show');return {type:'show',title:parsed.title,year:parsed.year,season,episode,episodeTitle:clean(cut(after))}}
 let parsed=titleYear(base);const fromFolder=titleYear(dirs.at(-1)||'');if(!parsed.year&&fromFolder.year)parsed=fromFolder;return {type:'movie',title:parsed.title||clean(base),year:parsed.year};
}
export function videoFile(name,mime=''){return mime.startsWith('video/')||/\.(mp4|mkv|webm|m4v|avi|mov|ts|m2ts|mpeg|mpg|ogv)$/i.test(name)}
export function subtitleFile(name){return /\.(srt|vtt|ass|ssa)$/i.test(name)}
export function quality(file){const n=file.name;return /2160p|\b4k\b/i.test(n)?2160:/1080p/i.test(n)?1080:/720p/i.test(n)?720:Number(file.height||0)}
export function catalog(files){const groups=new Map();for(const file of files){const parsed=parseName(file.name,file.path);const id=parsed.type+':'+key(parsed.title)+':'+(parsed.year||'');let title=groups.get(id);if(!title){title={id,...parsed,files:[],modifiedTime:file.modifiedTime||''};groups.set(id,title)}title.files.push({...file,parsed});if((file.modifiedTime||'')>title.modifiedTime)title.modifiedTime=file.modifiedTime||''}
 for(const title of groups.values()){title.files.sort((a,b)=>title.type==='show'?(a.parsed.season-b.parsed.season||a.parsed.episode-b.parsed.episode||quality(b)-quality(a)):(quality(b)-quality(a)||Number(b.size)-Number(a.size)));if(title.type==='show'){const seen=new Set();title.files=title.files.filter(f=>{const k=f.parsed.season+':'+f.parsed.episode;if(seen.has(k))return false;seen.add(k);return true})}}
 return [...groups.values()].sort((a,b)=>a.title.localeCompare(b.title));}
function subStem(name){return key(name.replace(/\.(srt|vtt|ass|ssa)$/i,'').replace(/[ ._\-](?:en|eng|english|ms|may|malay|zh|chi|chinese|ta|tam|tamil|hi|hin|hindi|id|ind|indonesian|forced|sdh|cc)(?:[ ._\-](?:forced|sdh|cc))?$/i,''))}
export function attachSubtitles(videos,subs){return videos.map(v=>{const stem=key(v.name.replace(/\.[^.]+$/,''));const parsed=parseName(v.name,v.path);return {...v,subtitles:subs.filter(s=>{if(s.source!==v.source||s.sourceFolder!==v.sourceFolder)return false;const samePath=s.path===v.path||s.path.replace(/\/(?:subs|subtitles)$/i,'')===v.path||(!v.path&&/^(?:subs|subtitles)$/i.test(s.path));if(!samePath)return false;if(subStem(s.name)===stem)return true;const sp=parseName(s.name,s.path);return parsed.type==='show'&&sp.type==='show'&&key(parsed.title)===key(sp.title)&&parsed.season===sp.season&&parsed.episode===sp.episode})}})}
export function toVtt(text,name){text=text.replace(/^\uFEFF/,'').replace(/\r\n?/g,'\n');if(/^WEBVTT/.test(text))return text;
 if(/\.(ass|ssa)$/i.test(name)){let format=['Layer','Start','End','Style','Name','MarginL','MarginR','MarginV','Effect','Text'];const cues=[];for(const line of text.split('\n')){if(line.startsWith('Format:'))format=line.slice(7).split(',').map(x=>x.trim());if(!line.startsWith('Dialogue:'))continue;const values=line.slice(9).trim().split(',');const pos=format.indexOf('Text');if(pos<0)continue;const body=values.slice(pos).join(',').replace(/\{[^}]*\}/g,'').replace(/\\[Nn]/g,'\n').replace(/\\h/g,' ');const start=values[format.indexOf('Start')],end=values[format.indexOf('End')];if(!start||!end)continue;const time=s=>s.trim().replace(/^(\d):/,'0$1:').replace(/\.(\d{2})$/,'.$10');cues.push(`${time(start)} --> ${time(end)}\n${body}`)}return 'WEBVTT\n\n'+cues.join('\n\n')+'\n'}
 return 'WEBVTT\n\n'+text.replace(/(\d{2}:\d{2}:\d{2}),(\d{3})/g,'$1.$2');
}
